// T-01 QA: integration tests for src/ratings/notch.mjs through its public exports.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

import * as notch from '../../../src/ratings/notch.mjs';

const { RATING_SCALE, notchChange, notchCalculator } = notch;

const EXPECTED_SCALE = ['AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-', 'BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-', 'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-'];
const INVALID = ['', '   ', 'D', 'NR', 'Baa1', 'AAA+', 'CCC--', 'BBB +', 'BBB−', null, undefined, 3, {}];
const describeValue = (v) => (typeof v === 'string' ? JSON.stringify(v) : v === undefined ? 'undefined' : JSON.stringify(v));

const here = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(here, '../../..');
const notchSrcPath = path.join(repoRoot, 'src/ratings/notch.mjs');

test('AC-1: RATING_SCALE deep-equals the 19 grades, is an array of length 19', () => {
  assert.deepEqual([...RATING_SCALE], EXPECTED_SCALE);
  assert.equal(Array.isArray(RATING_SCALE), true);
  assert.equal(RATING_SCALE.length, 19);
});

test('AC-1: RATING_SCALE is frozen and cannot be mutated by consumers', () => {
  assert.equal(Object.isFrozen(RATING_SCALE), true);
  assert.equal(Reflect.set(RATING_SCALE, 0, 'X'), false);
  assert.equal(RATING_SCALE[0], 'AAA');
  assert.throws(() => { RATING_SCALE[0] = 'X'; }, TypeError);
  assert.throws(() => { RATING_SCALE.push('D'); }, TypeError);
  assert.equal(RATING_SCALE.length, 19);
  assert.equal(RATING_SCALE[0], 'AAA');
});

const CHANGE_TABLE = [
  ['AC-2: BBB+ -> BB+ is 3', 'BBB+', 'BB+', 3],
  ['AC-2: BBB+ -> BBB- is 2', 'BBB+', 'BBB-', 2],
  ['AC-2: BBB+ -> BBB is 1', 'BBB+', 'BBB', 1],
  ['AC-2: BB+ -> BBB+ is -3', 'BB+', 'BBB+', -3],
  ['AC-2: BBB -> BBB+ is -1', 'BBB', 'BBB+', -1],
  ['AC-2: AAA -> CCC- is 18 (not clamped)', 'AAA', 'CCC-', 18],
  ['AC-2: CCC- -> AAA is -18 (not clamped)', 'CCC-', 'AAA', -18],
];
for (const [name, p, c, expected] of CHANGE_TABLE) {
  test(name, () => {
    const r = notchChange(p, c);
    assert.equal(r, expected);
    assert.equal(Number.isInteger(r), true);
  });
}

test('AC-2: A -> A is +0, not -0', () => {
  const r = notchChange('A', 'A');
  assert.equal(Object.is(r, 0), true);
  assert.equal(Number.isInteger(r), true);
});

test('AC-3: notchChange normalises whitespace and case', () => {
  assert.equal(notchChange(' bbb+ ', 'BB+'), 3);
  assert.equal(notchChange('aaa', 'Ccc-'), 18);
  assert.equal(notchChange('\tBb+\n', 'bbb+'), -3);
});

test('AC-3: notchCalculator("bbb+", " bb+") normalises input', () => {
  assert.deepEqual(notchCalculator('bbb+', ' bb+'), { notches: 3, direction: 'downgrade', wl: 2 });
});

for (const bad of INVALID) {
  test(`AC-4: notchChange throws RangeError for ${describeValue(bad)} as previous`, () => {
    assert.throws(() => notchChange(bad, 'BBB'), (e) => e instanceof RangeError);
  });
  test(`AC-4: notchChange throws RangeError for ${describeValue(bad)} as current`, () => {
    assert.throws(() => notchChange('BBB', bad), (e) => e instanceof RangeError);
  });
  test(`AC-4: notchCalculator throws RangeError for ${describeValue(bad)} as previous`, () => {
    assert.throws(() => notchCalculator(bad, 'BBB'), (e) => e instanceof RangeError);
  });
  test(`AC-4: notchCalculator throws RangeError for ${describeValue(bad)} as current`, () => {
    assert.throws(() => notchCalculator('BBB', bad), (e) => e instanceof RangeError);
  });
}

test('AC-4: missing argument throws RangeError in both functions', () => {
  assert.throws(() => notchChange('BBB'), (e) => e instanceof RangeError);
  assert.throws(() => notchCalculator('BBB'), (e) => e instanceof RangeError);
  assert.throws(() => notchChange(), (e) => e instanceof RangeError);
  assert.throws(() => notchCalculator(), (e) => e instanceof RangeError);
});

test('AC-4: invalid input never yields a value (no 0/NaN/undefined fallback)', () => {
  for (const bad of INVALID) {
    for (const fn of [notchChange, notchCalculator]) {
      let returned = false;
      try { fn(bad, 'BBB'); returned = true; } catch (e) { assert.ok(e instanceof RangeError); }
      try { fn('BBB', bad); returned = true; } catch (e) { assert.ok(e instanceof RangeError); }
      assert.equal(returned, false);
    }
  }
});

test('AC-4 edge: look-alike, inner whitespace and unmapped notations are rejected', () => {
  for (const bad of ['SD', 'BBB −', 'BB B', ' B B B ', 'bbb +', ' BBB x']) {
    assert.throws(() => notchChange(bad, 'BBB'), RangeError);
    assert.throws(() => notchCalculator('BBB', bad), RangeError);
  }
});

test('AC-4 edge: boxed string is rejected with RangeError', () => {
  assert.throws(() => notchChange(new String('BBB'), 'BBB'), RangeError);
  assert.throws(() => notchCalculator('BBB', new String('BBB')), RangeError);
});

test('AC-5: BBB+ -> BB+ is { 3, downgrade, 2 } (corrected POC example)', () => {
  assert.deepEqual(notchCalculator('BBB+', 'BB+'), { notches: 3, direction: 'downgrade', wl: 2 });
});

test('AC-6: BBB+ -> BBB- is { 2, downgrade, 1 }', () => {
  assert.deepEqual(notchCalculator('BBB+', 'BBB-'), { notches: 2, direction: 'downgrade', wl: 1 });
});

test('AC-7: BBB+ -> BBB is { 1, downgrade, 0 } (1-notch downgrade gives calculator WL 0)', () => {
  assert.deepEqual(notchCalculator('BBB+', 'BBB'), { notches: 1, direction: 'downgrade', wl: 0 });
});

test('AC-8: AAA -> CCC- is { 18, downgrade, 2 }', () => {
  assert.deepEqual(notchCalculator('AAA', 'CCC-'), { notches: 18, direction: 'downgrade', wl: 2 });
});

test('AC-8: A -> BBB+ is WL 1 and A -> BBB is WL 2 (2->3 boundary)', () => {
  assert.deepEqual(notchCalculator('A', 'BBB+'), { notches: 2, direction: 'downgrade', wl: 1 });
  assert.deepEqual(notchCalculator('A', 'BBB'), { notches: 3, direction: 'downgrade', wl: 2 });
});

test('AC-9: BB -> BBB is { -3, upgrade, 0 }', () => {
  assert.deepEqual(notchCalculator('BB', 'BBB'), { notches: -3, direction: 'upgrade', wl: 0 });
});

test('AC-9: BBB -> BBB+ is -1 and CCC- -> AAA is -18, both upgrade WL 0', () => {
  assert.deepEqual(notchCalculator('BBB', 'BBB+'), { notches: -1, direction: 'upgrade', wl: 0 });
  assert.deepEqual(notchCalculator('CCC-', 'AAA'), { notches: -18, direction: 'upgrade', wl: 0 });
});

test('AC-10: A -> A is { +0, unchanged, 0 }', () => {
  const r = notchCalculator('A', 'A');
  assert.deepEqual(r, { notches: 0, direction: 'unchanged', wl: 0 });
  assert.equal(Object.is(r.notches, 0), true);
});

test('AC-10: " a" -> "A " is the same unchanged result with +0', () => {
  const r = notchCalculator(' a', 'A ');
  assert.deepEqual(r, { notches: 0, direction: 'unchanged', wl: 0 });
  assert.equal(Object.is(r.notches, 0), true);
});

test('AC-11: result is a plain object with exactly notches, direction, wl', () => {
  const r = notchCalculator('BBB+', 'BB+');
  assert.deepEqual(Object.keys(r).sort(), ['direction', 'notches', 'wl']);
  assert.equal(Object.getPrototypeOf(r), Object.prototype);
});

test('AC-11: result is synchronous, not a Promise', () => {
  const r = notchCalculator('BBB+', 'BB+');
  assert.equal(r instanceof Promise, false);
  assert.equal(typeof r.then, 'undefined');
});

test('AC-11: each call returns a fresh object (mutation does not leak)', () => {
  const r1 = notchCalculator('BBB+', 'BB+');
  r1.wl = 99;
  const r2 = notchCalculator('BBB+', 'BB+');
  assert.equal(r2.wl, 2);
  assert.notEqual(r1, r2);
  assert.notEqual(notchCalculator('A', 'A'), notchCalculator('A', 'A'));
});

// Exhaustive loop over all 361 ordered pairs.
const pairs = [];
for (const p of RATING_SCALE) for (const c of RATING_SCALE) pairs.push([p, c]);

test('AC-16: all 361 ordered pairs, notches equals notchChange and is an integer (+0 for unchanged)', () => {
  assert.equal(pairs.length, 361);
  for (const [p, c] of pairs) {
    const d = notchChange(p, c);
    const r = notchCalculator(p, c);
    assert.equal(Number.isInteger(d), true, `${p}->${c}`);
    assert.equal(d, EXPECTED_SCALE.indexOf(c) - EXPECTED_SCALE.indexOf(p), `${p}->${c} index diff`);
    assert.equal(r.notches, d, `${p}->${c}`);
    assert.equal(Object.is(r.notches, d), true, `${p}->${c} sign of zero`);
    if (p === c) assert.equal(Object.is(d, 0), true, `${p}->${c} +0`);
  }
});

test('AC-16: all 361 ordered pairs, direction follows the sign of d', () => {
  for (const [p, c] of pairs) {
    const d = notchChange(p, c);
    const expected = d > 0 ? 'downgrade' : d < 0 ? 'upgrade' : 'unchanged';
    assert.equal(notchCalculator(p, c).direction, expected, `${p}->${c}`);
  }
});

test('AC-16: all 361 ordered pairs, wl follows Indicator 13 thresholds; counts 208/17/136', () => {
  const counts = [0, 0, 0];
