+// Rating scale and notch calculator (REQ-06-02). Pure functions, no I/O.
+
+export const RATING_SCALE = Object.freeze([
+  'AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-',
+  'BBB+', 'BBB', 'BBB-', 'BB+', 'BB', 'BB-',
+  'B+', 'B', 'B-', 'CCC+', 'CCC', 'CCC-',
+]);
+
+// Validates one rating argument and returns its index on RATING_SCALE.
+// Valid: a primitive string that, after trim() and upper-casing, is a grade.
+function indexOfRating(name, value) {
+  const index = typeof value === 'string' ? RATING_SCALE.indexOf(value.trim().toUpperCase()) : -1;
+  if (index === -1) {
+    const received = typeof value === 'string' ? JSON.stringify(value) : String(typeof value === 'object' && value !== null ? '[object]' : value);
+    throw new RangeError(`${name} is not a valid rating: ${received}`);
+  }
+  return index;
+}
+
+// Signed notch difference: positive = downgrade, negative = upgrade.
+export function notchChange(previous, current) {
+  const from = indexOfRating('previous', previous);
+  const to = indexOfRating('current', current);
+  return to - from + 0; // "+ 0" turns -0 into +0
+}
+
+// Indicator 13 thresholds: d<=1 -> 0, d===2 -> 1, d>=3 -> 2.
+export function notchCalculator(previous, current) {
+  const notches = notchChange(previous, current);
+  const direction = notches > 0 ? 'downgrade' : notches < 0 ? 'upgrade' : 'unchanged';
+  const wl = notches <= 1 ? 0 : notches === 2 ? 1 : 2;
+  return { notches, direction, wl };
+}
